"use client"
import { useCallback, useEffect, useState } from "react"
import { AtSign, CheckCircle2, CreditCard, MessageSquare, Rocket, Users, Inbox, type LucideIcon } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { EmptyState } from "@atlas/ui-web/compositions/EmptyState/EmptyState"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemMedia,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Tabs } from "@atlas/ui-web/patterns/Tabs/Tabs"
import {
  NOTIFICATIONS_INITIAL,
  SCENARIOS,
  type NotificationItem,
  type NotificationKind,
  type Scenario,
} from "../schema"

const ICONS: Record<NotificationKind, LucideIcon> = {
  mention: AtSign,
  approval: CheckCircle2,
  payment: CreditCard,
  comment: MessageSquare,
  deploy: Rocket,
  invite: Users,
}

const LOAD_DELAY_MS = 900

const column: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: "var(--atlas-spacing-4)",
  paddingInline: "var(--atlas-spacing-4)",
  paddingBlock: "var(--atlas-spacing-4)",
}

function LoadingList() {
  return (
    <div aria-busy="true" aria-label="Loading notifications" style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)" }}>
      {[0, 1, 2, 3, 4, 5].map((i) => (
        <div key={i} style={{ display: "flex", gap: "var(--atlas-spacing-3)", alignItems: "center" }}>
          <Skeleton shape="circle" />
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            <Skeleton />
            <Skeleton style={{ inlineSize: "60%" }} />
          </div>
        </div>
      ))}
    </div>
  )
}

export function Notifications() {
  const [items, setItems] = useState<NotificationItem[]>(NOTIFICATIONS_INITIAL)
  const [scenario, setScenario] = useState<Scenario>("default")
  const [loading, setLoading] = useState(true)
  const [failed, setFailed] = useState(false)
  const [approved, setApproved] = useState<Record<string, boolean>>({})
  const [tab, setTab] = useState("all")

  const load = useCallback((s: Scenario) => {
    setLoading(true)
    setFailed(false)
    const t = setTimeout(() => {
      setFailed(s === "error")
      setLoading(false)
    }, LOAD_DELAY_MS)
    return () => clearTimeout(t)
  }, [])

  useEffect(() => load("default"), [load])

  const pick = (s: Scenario) => {
    setScenario(s)
    if (s === "default") setItems(NOTIFICATIONS_INITIAL)
    load(s)
  }

  const retry = () => pick("default")

  const setRead = (id: string, read: boolean) =>
    setItems((prev) => prev.map((n) => (n.id === id ? { ...n, read } : n)))
  const markAllRead = () => setItems((prev) => prev.map((n) => ({ ...n, read: true })))
  const approve = (id: string) => {
    setApproved((a) => ({ ...a, [id]: true }))
    setRead(id, true)
  }

  const visibleItems = scenario === "empty" ? [] : items
  const unreadCount = visibleItems.filter((n) => !n.read).length

  const renderList = (filter: "all" | "unread") => {
    if (loading) return <LoadingList />
    if (failed) {
      return (
        <Alert
          variant="danger"
          title="Couldn't load notifications"
          description="Check your connection and try again."
          actions={<Button variant="outline" size="sm" onClick={retry}>Try again</Button>}
        />
      )
    }
    const list = filter === "unread" ? visibleItems.filter((n) => !n.read) : visibleItems
    if (list.length === 0) {
      return filter === "unread" && visibleItems.length > 0 ? (
        <EmptyState icon={<Inbox />} title="You're all caught up" description="No unread notifications right now." />
      ) : (
        <EmptyState icon={<Inbox />} title="No notifications yet" description="Mentions, approvals and updates will show up here." />
      )
    }
    return (
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        {list.map((n) => {
          const Icon = ICONS[n.kind]
          const done = approved[n.id]
          return (
            <ListItem key={n.id} as="li" variant={n.read ? "default" : "outline"}>
              <ListItemMedia type="tile" decorative><Icon /></ListItemMedia>
              <ListItemContent>
                <ListItemTitle style={{ fontWeight: n.read ? "var(--atlas-font-weight-regular)" : "var(--atlas-font-weight-semibold)" }}>
                  {n.title}
                </ListItemTitle>
                <ListItemDescription>{n.where} · {n.when}</ListItemDescription>
                <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)", marginBlockStart: "var(--atlas-spacing-2)" }}>
                  <Badge size="sm" variant={n.read ? "neutral" : "primary"} dot={!n.read}>{n.read ? "Read" : "Unread"}</Badge>
                  {n.kind === "payment" && <Badge size="sm" variant="danger">Failed</Badge>}
                  {n.kind === "approval" && (
                    done
                      ? <Badge size="sm" variant="success">Approved</Badge>
                      : <Button size="xs" variant="primary" onClick={() => approve(n.id)}>Approve</Button>
                  )}
                </div>
              </ListItemContent>
              <ListItemActions>
                <Button size="xs" variant="ghost" onClick={() => setRead(n.id, !n.read)}>
                  {n.read ? "Mark as unread" : "Mark as read"}
                </Button>
              </ListItemActions>
            </ListItem>
          )
        })}
      </ul>
    )
  }

  return (
    <div style={column}>
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-3)" }}>
        <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h1)", fontWeight: "var(--atlas-font-weight-bold)", color: "var(--atlas-foreground)", lineHeight: "var(--atlas-line-height-tight)" }}>
          Notifications
        </h1>
        <Button variant="outline" size="sm" disabled={loading || failed || unreadCount === 0} onClick={markAllRead}>
          Mark all as read
        </Button>
      </header>

      <Tabs
        variant="pill"
        size="sm"
        activeTab={tab}
        onTabChange={setTab}
        items={[
          { id: "all", label: "All", content: renderList("all") },
          { id: "unread", label: "Unread", badge: loading || failed ? undefined : unreadCount, content: renderList("unread") },
        ]}
      />

      <nav aria-label="Demo state" style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: "var(--atlas-spacing-1)", borderBlockStart: "var(--atlas-border-width-1) solid var(--atlas-border-subtle)", paddingBlockStart: "var(--atlas-spacing-3)" }}>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>Preview state:</span>
        {SCENARIOS.map((s) => (
          <Button key={s.id} size="xs" variant={scenario === s.id ? "secondary" : "ghost"} aria-pressed={scenario === s.id} onClick={() => pick(s.id)}>
            {s.label}
          </Button>
        ))}
      </nav>
    </div>
  )
}
